function switchModule(id){if(!models[id])return;window.WoodPDFTables?.close();navCollapsed.delete(P.has(id)?'wood':'concepts');setIntro(false);active=id;if(id==='building')view.mode='3d';if(id==='floor'&&states.floor.layout?.enabled)view.mode='2d';studio.chain=null;selected=id==='loads'?'beam1':null;tab='model';hideResults=false;plane='auto';$('planeSelect').value='auto';renderer.reset({nextScene:true});renderAll();}
