function bayDetailsHTML(r){const ratio=x=>Number.isFinite(x)?num(x):'Outside range';return `<div class="section-label">Sizing checks</div><table class="detail-table"><tr><th>Element</th><th>Governing</th><th>D/C</th></tr>${[['Panel',r.panel],['Beam',r.beam],['Girder',r.girder],['Column',r.column]].map(([name,item])=>`<tr><td>${name}</td><td>${esc(item.governing)}</td><td>${ratio(item.utilization)}</td></tr>`).join('')}</table><p class="studio-note">Demand/capacity ≤ 1 satisfies the checks shown. Unverified checks are not counted as passing. ${r.fire?'Panel and connection fire resistance are not verified by these member calculations.':''}</p><div class="section-label">Interior bay allocation</div><table class="detail-table">${Object.entries(r.quantity).map(([name,volume])=>{const u=window.BayUnits(states.floor,'cf');return `<tr><td>${name}</td><td>${num(volume*u.factor)} ${u.unit}</td></tr>`;}).join('')}</table><p class="studio-note">One interior column and one shared girder line per bay per floor. Edge beams are shared. ${r.stories} floor level(s): ${num(r.totalVolume*window.BayUnits(states.floor,'cf').factor)} ${window.BayUnits(states.floor,'cf').unit}. The final Building view counts its actual perimeter and interior members.</p><div class="section-label">Method and sources</div><p class="studio-note">Simply supported, dry-service, laterally braced members. Live deflection L/360; long-term deflection L/240 with 2D + L. Glulam dimensions use 1.5 in depth increments. Column effective length uses the taller floor/roof story when the roof load is included. The fire calculation screens 3 exposed beam faces and 4 exposed column faces. Vibration, bearing, connections and lateral stability require separate checks.</p><p class="studio-note"><a href="https://bay-design-tool.fastepp.com/about/" target="_blank" rel="noopener">Original tool scope</a> · <a href="https://www.apawood.org/engineered-wood-products/glulam/" target="_blank" rel="noopener">Glulam reference</a> · <a href="https://kalesnikoff.com/wp-content/uploads/2022/10/ESR-5105.pdf" target="_blank" rel="noopener">CLT catalog snapshot</a> · <a href="https://awc.org/wp-content/uploads/2021/12/AWC_TR10_20210427_AWCWebsite.pdf" target="_blank" rel="noopener">AWC TR10 fire method</a></p>`;}
function exportBaySchedule(){const r=P.floorDesign(states).bay;if(!r)return;const rows=[['Structure Lab · independent timber bay sizing'],['Element','Description','Width (in)','Depth (in)','Governing','Demand/capacity'],['Panel',r.panel.name,'',r.panel.t,r.panel.governing,r.panel.utilization],...['beam','girder','column'].map(key=>{const m=r[key];return [key,'Glulam reference values',m.b,m.h,m.governing,m.utilization];}),[],['Grid X (ft)',states.floor.beamSpan],['Grid Y (ft)',states.floor.girderSpan],['Supported floors',r.stories],['Story height (ft)',r.height],['Column effective height (ft)',r.columnEffectiveHeight],['Live load (psf)',r.live],['Additional dead load (psf)',r.dead],['Fire exposure (min)',r.fire],['Panel and connection fire resistance',r.fire?'Not verified':'No fire exposure selected'],['Structural depth (in)',r.totalDepth],['Interior bay / floor quantity (cf)',r.volume],['Repeated interior-bay total (cf)',r.totalVolume],['A1-A3 carbon (kgCO2e/m2)',r.carbon?.intensity??'EPD factors not set'],['Scope','Preliminary component sizing; not full code compliance or whole-building analysis']];const csv=rows.map(row=>row.map(v=>'"'+String(Number.isFinite(v)||typeof v!=='number'?v:'Outside range').replace(/"/g,'""')+'"').join(',')).join('\r\n');try{downloadBlob('StructureLab-Timber-Bay-Schedule.csv',new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));toast('Member schedule download started');}catch(e){toast('Download could not start. Please try again.');}}
function chartHTML(ch){
 const points=ch.series.filter(p=>p.every(Number.isFinite));if(!points.length)return '';
 const xmin=Math.min(...points.map(p=>p[0])),xmax=Math.max(...points.map(p=>p[0]));let ymin=Math.min(0,...points.map(p=>p[1])),ymax=Math.max(0,...points.map(p=>p[1]));if(ymax-ymin<1e-10)ymax=ymin+1;
 const xx=x=>28+(x-xmin)/(xmax-xmin||1)*236,yy=y=>99-(y-ymin)/(ymax-ymin)*76,base=yy(0),path=points.map((p,i)=>(i?'L':'M')+xx(p[0]).toFixed(2)+','+yy(p[1]).toFixed(2)).join(' ');
 return `<div class="section-label">${tr(ch.title)}</div><div class="chart"><svg viewBox="0 0 290 130" role="img" aria-label="${tr(ch.title)}"><path d="M28,${base} H264" fill="none" stroke="#c2ccdd" stroke-width="1"/><path d="${path} L264,${base} L28,${base} Z" fill="#cad9f866"/><path d="${path}" fill="none" stroke="#4972c4" stroke-width="2"/><text x="27" y="119" font-size="9" fill="#798ba8">${num(xmin)}</text><text x="262" y="119" text-anchor="end" font-size="9" fill="#798ba8">${num(xmax)} ${esc(ch.xunit||'ft')}</text><text x="264" y="13" text-anchor="end" font-size="10" fill="#4972c4">${num(Math.max(Math.abs(ymax),Math.abs(ymin)))} ${esc(ch.unit)}</text></svg></div><div class="chart-meta">${tr('Plot scaled to current result. Compare numerical values when changing inputs.')}</div>`;
}
